-- hrm.attendance_days: Trigger refuses updates when the period is locked; later changes create hrm.retro_adjustments (FR-XM-26).
drop function if exists hrm.todo_attendance_days_lock();
create or replace function hrm.tg_attendance_days_lock() returns trigger
language plpgsql as $fn$
declare
    v_status text;
begin
    -- The row is locked whatever its status, so a lock being taken is waited for and its result is the status read.
    for v_status in select p.status from hrm.attendance_periods p
                     where p.id in (case when tg_op <> 'INSERT' then old.period_id end, case when tg_op <> 'DELETE' then new.period_id end)
                     for share loop
        if v_status = 'locked' then
            raise exception 'attendance day % of %: its attendance period is locked; use a retroactive adjustment (FR-XM-26)', coalesce(new.work_date, old.work_date), coalesce(new.employment_id, old.employment_id)
                using errcode = '23514', constraint = 'ck_attendance_period_locked';
        end if;
    end loop;
    return case when tg_op = 'DELETE' then old else new end;
end
$fn$;
