-- hrm.attendance_periods: A locked period never reopens (FR-XM-26). Unlocking is allowed only if the locking run is cancelled before it is locked itself. Lock trigger covers attendance_days, leave_request_days, overtime_entries and approved regularization_requests dated in the period; changes after lock become hrm.retro_adjustments.
drop function if exists hrm.todo_attendance_periods_lock();
-- The locked attendance period of an employment's date: the period of the employment's pay group on the date, read with a share lock
-- (it waits for a lock being taken and is waited for by one); null when the date's period is open or there is none. Before the period's
-- first lock or processed day there is no attendance period row: the guard then meets the lock on the pay period row (the lock takes it
-- for update before it creates the attendance period) and reads again, so a write and a lock never pass each other (review S1.31 finding 4).
create or replace function hrm.locked_attendance_period(p_employment_id uuid, p_date date) returns uuid
language plpgsql as $fn$
declare
    v_group uuid;
    v_id uuid;
    v_status text;
begin
    select a.pay_group_id into v_group from hrm.employment_assignments a
     where a.employment_id = p_employment_id and a.valid_from <= p_date and (a.valid_to is null or a.valid_to > p_date)
     order by a.valid_from desc limit 1;
    if v_group is null then
        return null;
    end if;
    select p.id, p.status into v_id, v_status from hrm.attendance_periods p
     where p.pay_group_id = v_group and p.period_start <= p_date and p.period_end >= p_date
     for share;
    if v_id is null then
        perform 1 from hrm.pay_periods pp
         where pp.pay_group_id = v_group and pp.start_date <= p_date and pp.end_date >= p_date
         for share;
        select p.id, p.status into v_id, v_status from hrm.attendance_periods p
         where p.pay_group_id = v_group and p.period_start <= p_date and p.period_end >= p_date
         for share;
    end if;
    return case when v_status = 'locked' then v_id end;
end
$fn$;

create or replace function hrm.tg_attendance_periods_lock() returns trigger
language plpgsql as $fn$
begin
    if tg_op = 'DELETE' then
        if old.status = 'locked' then
            raise exception 'attendance period %: a locked period is never removed', old.id
                using errcode = '23514', constraint = 'ck_attendance_periods_lock';
        end if;
        return old;
    end if;
    if tg_op = 'UPDATE' and (new.company_id <> old.company_id or new.pay_group_id <> old.pay_group_id or new.pay_period_id <> old.pay_period_id
                             or new.period_start <> old.period_start or new.period_end <> old.period_end) then
        raise exception 'attendance period %: its pay group, pay period and dates never change', old.id
            using errcode = '23514', constraint = 'ck_attendance_periods_lock';
    end if;
    if new.status = 'locked' then
        if new.locked_at is null or new.lock_kind is null or new.locked_by is null
           or (new.lock_kind = 'payroll') <> (new.locked_by_run_id is not null) then
            raise exception 'attendance period %: a lock has its time, kind, who and (payroll) its run', new.id
                using errcode = '23514', constraint = 'ck_attendance_periods_lock';
        end if;
        if tg_op = 'UPDATE' and old.status = 'locked'
           and (to_jsonb(new) - array['reopen_workflow_instance_id', 'reopen_requested_by', 'reopen_reason', 'updated_at', 'updated_by', 'row_version'])
               <> (to_jsonb(old) - array['reopen_workflow_instance_id', 'reopen_requested_by', 'reopen_reason', 'updated_at', 'updated_by', 'row_version']) then
            raise exception 'attendance period %: a lock never changes (FR-XM-26)', old.id
                using errcode = '23514', constraint = 'ck_attendance_periods_lock';
        end if;
        return new;
    end if;
    if new.locked_at is not null or new.locked_by_run_id is not null or new.lock_kind is not null or new.locked_by is not null
       or new.unprocessed_accepted is not null or new.exceptions_accepted is not null then
        raise exception 'attendance period %: an open period has no lock', new.id
            using errcode = '23514', constraint = 'ck_attendance_periods_lock';
    end if;
    if tg_op = 'UPDATE' and old.status = 'locked' then
        -- Reopening (CR-095): only a payroll lock whose run was cancelled before it was locked itself; never an HR lock.
        if old.locked_by_run_id is null
           or not exists (select 1 from hrm.pay_runs r where r.company_id = old.company_id and r.id = old.locked_by_run_id and r.status = 'cancelled')
           or new.reopened_at is null or new.reopen_reason is null then
            raise exception 'attendance period %: it reopens only when the run that locked it is cancelled before it is locked; use a retroactive adjustment', old.id
                using errcode = '23514', constraint = 'ck_attendance_periods_lock';
        end if;
    end if;
    return new;
end
$fn$;
