-- One guard for the period's records (FR-XM-26). A leave day counts while its request is approved or waits for its cancellation (what
-- payroll reads, FR-HRM-LVE-07): a counted day is never added, changed or removed and an uncounted one never becomes counted, while a
-- waiting request's days may still end (rejected, withdrawn). Overtime is payable once approved: a locked day's entry is never added
-- or removed, never becomes payable or changes its minutes; payroll still marks approved overtime paid and the leave engine still
-- records the comp-off entry of converted overtime. A regularization never becomes approved for a locked date.
create or replace function hrm.tg_attendance_lock_guard() returns trigger
language plpgsql as $fn$
declare
    v_old uuid;
    v_new uuid;
begin
    if tg_table_name = 'leave_request_days' then
        if tg_op <> 'INSERT' then v_old := hrm.locked_attendance_period(old.employment_id, old.leave_date); end if;
        if tg_op <> 'DELETE' then v_new := hrm.locked_attendance_period(new.employment_id, new.leave_date); end if;
        if (tg_op <> 'INSERT' and v_old is not null and old.request_status in ('approved', 'cancel_requested')
               and (tg_op = 'DELETE' or new.request_status not in ('approved', 'cancel_requested')
                    or (to_jsonb(new) - array['request_status', 'updated_at', 'updated_by', 'row_version'])
                       <> (to_jsonb(old) - array['request_status', 'updated_at', 'updated_by', 'row_version'])))
           or (tg_op <> 'DELETE' and v_new is not null and new.request_status in ('approved', 'cancel_requested')
               and (tg_op = 'INSERT' or old.request_status not in ('approved', 'cancel_requested') or v_old is null)) then
            raise exception 'leave day % of %: its attendance period is locked; use a retroactive adjustment (FR-XM-26)', coalesce(new.leave_date, old.leave_date), coalesce(new.employment_id, old.employment_id)
                using errcode = '23514', constraint = 'ck_attendance_period_locked';
        end if;
    elsif tg_table_name = 'overtime_entries' then
        if tg_op <> 'INSERT' then v_old := hrm.locked_attendance_period(old.employment_id, old.work_date); end if;
        if tg_op <> 'DELETE' then v_new := hrm.locked_attendance_period(new.employment_id, new.work_date); end if;
        if tg_op <> 'UPDATE' and coalesce(v_old, v_new) is not null
           or tg_op = 'UPDATE' and coalesce(v_old, v_new) is not null and not (
                  v_old is not null and v_new is not null and new.employment_id = old.employment_id and new.work_date = old.work_date
                  and new.minutes = old.minutes and new.approved_minutes is not distinct from old.approved_minutes
                  and new.rate_multiplier = old.rate_multiplier and new.comp_off_minutes is not distinct from old.comp_off_minutes
                  and (new.status = old.status
                       or old.status = 'approved' and new.status = 'paid'
                       or old.status = 'submitted' and new.status in ('rejected', 'calculated'))) then
            raise exception 'overtime of % on %: its attendance period is locked; use a retroactive adjustment (FR-XM-26)', coalesce(new.employment_id, old.employment_id), coalesce(new.work_date, old.work_date)
                using errcode = '23514', constraint = 'ck_attendance_period_locked';
        end if;
    elsif tg_table_name = 'regularization_requests' then
        if new.status = 'approved' and (tg_op = 'INSERT' or old.status <> 'approved' or new.work_date <> old.work_date)
           and hrm.locked_attendance_period(new.employment_id, new.work_date) is not null then
            raise exception 'regularization of % on %: its attendance period is locked; use a retroactive adjustment (FR-XM-26)', new.employment_id, new.work_date
                using errcode = '23514', constraint = 'ck_attendance_period_locked';
        end if;
    end if;
    return case when tg_op = 'DELETE' then old else new end;
end
$fn$;
